//! PIDASHCONV-1554: Tier-1 proof corpus for the shared HTML normaliser.
//!
//! Every input is HTML a real client sends (tiptap extension outputs,
//! description/comment fixtures and contract-test payloads, plus the
//! Tier-1 survivors of the deleted `LXML_GOLDENS` table). The expected
//! outputs are live-lxml results generated by the committed
//! `corpus/generate_lxml_outputs.py` (lxml 6.1.0, recorded in the file).
//! Zero diffs is required: any mismatch is a Tier-1/2 regression.

use pidash_services::html_normalize::lxml_roundtrip;

const INPUTS: &str = include_str!("corpus/inputs.json");
const EXPECTED: &str = include_str!("corpus/expected.json");

#[test]
fn corpus_matches_live_lxml_with_zero_diffs() {
    let inputs: Vec<serde_json::Value> = serde_json::from_str(INPUTS).expect("inputs parse");
    let expected: serde_json::Value = serde_json::from_str(EXPECTED).expect("expected parses");
    let cases = expected
        .get("cases")
        .and_then(serde_json::Value::as_object)
        .expect("expected has cases");
    assert_eq!(
        inputs.len(),
        cases.len(),
        "inputs and expected drifted: regenerate with generate_lxml_outputs.py"
    );
    let mut diffs = Vec::new();
    for case in &inputs {
        let id = case
            .get("id")
            .and_then(serde_json::Value::as_str)
            .expect("id");
        let html = case
            .get("html")
            .and_then(serde_json::Value::as_str)
            .expect("html");
        let want = match cases.get(id) {
            Some(serde_json::Value::String(s)) => Some(s.clone()),
            Some(serde_json::Value::Null) => None,
            other => panic!("corpus case {id} has no expected output (found {other:?})"),
        };
        let got = lxml_roundtrip(html);
        if got != want {
            diffs.push((id.to_owned(), html.to_owned(), want, got));
        }
    }
    for (id, html, want, got) in &diffs {
        println!("DIFF {id} input={html:?}\n  want={want:?}\n  got ={got:?}");
    }
    assert!(
        diffs.is_empty(),
        "{} of {} corpus cases differ from live lxml",
        diffs.len(),
        inputs.len()
    );
}
